-- NUMS remap of the first Biology 12 set (0014), which had copied the MDCAT chapters into NUMS.
-- Chapters 13 and 14 (homeostasis, urinary system), 19 (chromosomes and DNA) and 20 (biotechnology) are not NUMS units.
DELETE FROM bank_questions WHERE bank = 'nums' AND subject = 'Biology'
  AND (question_id BETWEEN 'BIO-0001' AND 'BIO-0092' OR question_id BETWEEN 'BIO-0359' AND 'BIO-0476');
-- Chapter 21 (immunity) belongs to NUMS "Life processes in animals and plants" (immune and lymphatic system).
UPDATE bank_questions SET chapter = 'Life processes in animals and plants'
  WHERE bank = 'nums' AND subject = 'Biology' AND question_id BETWEEN 'BIO-0477' AND 'BIO-0530';

-- The UHS 2026 past paper (0020) also copied MDCAT chapters into NUMS. Move its Biology questions to the NUMS units,
-- and take out the ones on topics NUMS doesn't list (excretion and thermoregulation, DNA, chromosomes, biotechnology).
UPDATE bank_questions SET chapter = 'Life processes in animals and plants'
  WHERE bank = 'nums' AND subject = 'Biology' AND chapter IN ('Human physiology', 'Immunity') AND question_id IN (
    'BIO-9002', 'BIO-9008', 'BIO-9013', 'BIO-9018', 'BIO-9024', 'BIO-9027', 'BIO-9039', 'BIO-9040', 'BIO-9053', 'BIO-9054',
    'BIO-9055', 'BIO-9056', 'BIO-9058', 'BIO-9061', 'BIO-9062', 'BIO-9063', 'BIO-9064', 'BIO-9065', 'BIO-9068', 'BIO-9076',
    'BIO-9079');
UPDATE bank_questions SET chapter = 'Support and movement'
  WHERE bank = 'nums' AND subject = 'Biology' AND chapter = 'Human physiology' AND question_id IN (
    'BIO-9006', 'BIO-9010', 'BIO-9011', 'BIO-9036', 'BIO-9050', 'BIO-9074', 'BIO-9077');
DELETE FROM bank_questions
  WHERE bank = 'nums' AND subject = 'Biology' AND question_id BETWEEN 'BIO-9001' AND 'BIO-9999'
  AND chapter IN ('Homeostasis', 'Chromosomes and DNA', 'Biotechnology');
